  FROM notable_npcs WHERE slug IN ('set','anubis','apepi','amon','anhur','ammit','bes','osiris','ra','thoth','isis','horus','bennu','apis','sebek') AND system = 'palladium-fantasy';

-- Osiris has no stat block (printed 48-49): he is dead, cut into fourteen
-- pieces that are artifacts in their own right, and no one god owns them, so
-- they ride no NPC row. One magic gear row carries the set.
INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book)
VALUES ('body-parts-of-osiris', 'Body Parts of Osiris', 'rifts', 'magic', NULL, NULL,
  'Not sold; each part is valued at no less than 1 million credits.',
  'Right femur as a staff: 4D6 M.D., double to vampires, zombies and animated dead. Left femur as a returning club: 4D6 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL,
  'The fourteen giant-sized pieces of the slain god, each indestructible, casting as a 15th level spell caster. A necromancer bonded to a hand, a foot, the skull or the rib cage gains 500 M.D.C., +2 to all saves and supernatural P.S. (the rib cage another 300 M.D.C. and immunity to gases); bonuses from several parts stack. The parts: RIGHT HAND (index finger missing) doubles P.S. and grips telekinetically, carrying 500 lb or crushing for 1D4x10 M.D. a melee. RIGHT INDEX FINGER finds secret compartments and doors (89%) and dowses water, ley lines and nexus points within 100 miles. LEFT HAND (gold) dispels magic barriers, heals (2D6x10 S.D.C./hit points or 2D6 M.D.C.) and negates poison, each six times a day. LEFT FOOT doubles speed (not for cyborgs or robots), +5 to dodge, leaps 30 ft up or 25 ft across, leap kicks at double damage. RIB CAGE (gold) makes the wearer a 50 M.D.C. mega-damage being regenerating hourly, half damage from M.D. fire and cold, none from ordinary fire and cold, +2 to all saves. RIGHT EYE (diamond) sees the invisible, astral travellers and elementals, nightvision 120 ft, x-ray sight through 5 ft of anything but lead. LEFT EYE (ruby) tracks, finds secret doors and identifies plants at 80% and recognizes enchantment; its tear, twice a day, neutralizes poison or restores 2D6 S.D.C./hit points. RIGHT FEMUR is an 8 ft staff that also throws a 6D6 M.D. lightning bolt every other melee and makes its holder immune to electricity. LEFT FEMUR is a returning club that throws a 6D6 M.D. fire ball every other melee and makes its holder immune to M.D. fire, heat and nuclear energy. TONGUE (silver medallion) speaks and understands every language, detects lies at 60% and shields against charms, hypnosis and charismatic aura. SKULL MASK gives +2 I.Q., +6 to save vs psionics, +5 vs magic, poison and disease, +2 vs horror factor, nightvision 90 ft, understanding of all languages, Horror Factor 13 and bio-regeneration of 2D6 six times a day; it cannot come off before its wearer dies, who rolls for insanity every year. LUNGS (squeezed with P.S. 16) release wind rush, cloud of smoke, repel animals or wisps of confusion, six times in 24 hours. KIDNEY (bronze) gives +5 to save vs magic and detects and neutralizes any poison. HEART (platinum) gives +10 to save vs horror factor and +5 to all saves, and six times a day each senses evil and magic, turns 2D4x10 dead, removes curses, heals by touch (4D6) and resurrects someone dead under 48 hours (30%); it burns evil beings who touch it for 2D4x10 M.D. and selfish ones for 2D6 M.D. Isis keeps about a third of them enshrined at any time, and Set''s minions steal them.',
  'Rifts World Book 4: Africa p.48-49');

SELECT 'the body parts of Osiris are one magic row' AS assertion, count(*) AS got, 1 AS want
  FROM gear WHERE slug = 'body-parts-of-osiris' AND category = 'magic' AND cost IS NULL;

